-- Source: migrations/20260723100000_article_updated_at_exclude_views.sql
-- Keep articles.updated_at as "last edited", not "last viewed".
-- record_article_view only increments view_count; that update must not bump updated_at.
-- Profiles keep the simple touch_updated_at trigger.

create or replace function public.touch_articles_updated_at()
returns trigger
language plpgsql
as $$
begin
  if (to_jsonb(NEW) - 'view_count' - 'updated_at')
     = (to_jsonb(OLD) - 'view_count' - 'updated_at') then
    NEW.updated_at = OLD.updated_at;
    return NEW;
  end if;
  NEW.updated_at = now();
  return NEW;
end;
$$;

drop trigger if exists trg_articles_touch on public.articles;
create trigger trg_articles_touch
  before update on public.articles
  for each row execute function public.touch_articles_updated_at();


-- Source: migrations/20260723110000_repair_article_published_at.sql
-- One-time repair: restore published_at from the author form Date + Time.
-- Those fields were not overwritten when updateArticle reset published_at on
-- every save. Also clear view-polluted updated_at where we can infer it.
--
-- Asia/Ho_Chi_Minh: article_date/time are local editorial values (no tz).

alter table public.articles disable trigger trg_articles_touch;

update public.articles a
set
  published_at = (
    (a.article_date + coalesce(a.article_time, time '00:00'))
    at time zone 'Asia/Ho_Chi_Minh'
  ),
  updated_at = case
    -- Last save rewrote published_at and bumped updated_at together → keep edit time.
    when a.updated_at <= a.published_at + interval '2 minutes'
      then a.updated_at
    -- published_at already matched the form date; later updated_at is view noise.
    when a.published_at is not null
         and (a.published_at at time zone 'Asia/Ho_Chi_Minh')::date = a.article_date
      then a.published_at
    -- published_at was an overwrite from a later edit; that stamp is the last edit.
    when a.published_at is not null
      then a.published_at
    else (
      (a.article_date + coalesce(a.article_time, time '00:00'))
      at time zone 'Asia/Ho_Chi_Minh'
    )
  end
where a.status = 'published'
  and a.article_date is not null;

alter table public.articles enable trigger trg_articles_touch;


-- Source: migrations/20260724100000_article_claps.sql
-- Independent clap reactions (one per IP per article), separate from hearts.
-- Visitors may clap and heart the same article at the same time.

create table if not exists public.article_claps (
  id          uuid primary key default gen_random_uuid(),
  article_id  uuid not null references public.articles (id) on delete cascade,
  ip_hash     text not null,
  created_at  timestamptz not null default now(),
  unique (article_id, ip_hash)
);
create index if not exists article_claps_article_idx
  on public.article_claps (article_id);

create or replace function public.get_claps(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip      text := public.client_ip_hash();
  v_count   int;
  v_clapped boolean;
begin
  select count(*) into v_count from public.article_claps where article_id = p_article;
  select exists (
    select 1 from public.article_claps where article_id = p_article and ip_hash = v_ip
  ) into v_clapped;
  return json_build_object('clapped', v_clapped, 'count', v_count);
end $$;

create or replace function public.toggle_clap(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip      text := public.client_ip_hash();
  v_clapped boolean;
  v_count   int;
begin
  if not exists (select 1 from public.articles where id = p_article) then
    raise exception 'article not found';
  end if;

  if exists (
    select 1 from public.article_claps where article_id = p_article and ip_hash = v_ip
  ) then
    delete from public.article_claps where article_id = p_article and ip_hash = v_ip;
    v_clapped := false;
  else
    insert into public.article_claps (article_id, ip_hash)
      values (p_article, v_ip) on conflict do nothing;
    v_clapped := true;
  end if;

  select count(*) into v_count from public.article_claps where article_id = p_article;
  return json_build_object('clapped', v_clapped, 'count', v_count);
end $$;

alter table public.article_claps enable row level security;

grant execute on function public.get_claps(uuid)   to anon, authenticated;
grant execute on function public.toggle_clap(uuid) to anon, authenticated;


