-- Source: migrations/20260728130000_admin_storage_write.sql
-- Let admins manage storage objects belonging to other authors.
--
-- Every articles/article_media policy already grants admins write access via
-- public.is_admin(), but the storage policies did not: they required the first
-- path segment (the owner's user id) to equal auth.uid(). Media lives under
-- '<author-uuid>/media/...', so an admin editing someone else's article could
-- upload (files go under the admin's own folder) but could NOT delete the
-- original author's files.
--
-- That failed silently: supabase.storage.remove() does not throw when RLS
-- denies the delete, so syncMedia() in news-app/src/lib/articles.js removed the
-- article_media row while the file stayed behind as an orphan in the bucket.

drop policy if exists storage_auth_write on storage.objects;
create policy storage_auth_write on storage.objects for insert to authenticated
  with check (
    bucket_id in ('avatars', 'article-media')
    and (
      (storage.foldername(name))[1] = auth.uid()::text
      or public.is_admin()
    )
  );

drop policy if exists storage_auth_modify on storage.objects;
create policy storage_auth_modify on storage.objects for update to authenticated
  using (
    bucket_id in ('avatars', 'article-media')
    and (
      (storage.foldername(name))[1] = auth.uid()::text
      or public.is_admin()
    )
  );

drop policy if exists storage_auth_delete on storage.objects;
create policy storage_auth_delete on storage.objects for delete to authenticated
  using (
    bucket_id in ('avatars', 'article-media')
    and (
      (storage.foldername(name))[1] = auth.uid()::text
      or public.is_admin()
    )
  );


-- Source: migrations/20260730120000_notifications.sql
-- =============================================================================
-- In-site bell notifications for admins + authors (newsroom app).
--
-- Every object here is namespaced `newsroom_*`. This project already has
-- unrelated `notifications` / `hr_notifications` tables, and an unprefixed
-- `create table if not exists public.notifications` silently skips them, after
-- which every statement below fails with 42703 (column "recipient_id" does not
-- exist). Nothing in this file touches those tables or the existing
-- `notification_type` enum.
--
-- Events are emitted by database triggers rather than client code, so they fire
-- no matter which path performed the write (dashboard, article page, RPC).
--
--   article_published  — first transition into 'published' (edits never notify)
--   article_deleted    — the article row was removed
--   views_milestone    — view_count crossed a threshold (see newsroom_view_milestones)
--   hearts_milestone   — hearts crossed a threshold (see newsroom_reaction_milestones)
--   claps_milestone    — claps crossed a threshold
--
-- Recipients are the article's author plus every admin. The actor who caused the
-- event never notifies themselves. One row per recipient per event, deduped by
-- dedupe_key so a milestone can only ever land once.
-- =============================================================================

do $$ begin
  create type public.newsroom_notification_type as enum (
    'article_published',
    'article_deleted',
    'views_milestone',
    'hearts_milestone',
    'claps_milestone'
  );
exception when duplicate_object then null; end $$;

-- article_id is intentionally NOT a foreign key: an 'article_deleted' notice has
-- to outlive the article it refers to. Title/slug are snapshotted for the same
-- reason — the notification stays readable after the row is gone.
create table if not exists public.newsroom_notifications (
  id            uuid primary key default gen_random_uuid(),
  recipient_id  uuid not null references public.profiles (id) on delete cascade,
  type          public.newsroom_notification_type not null,
  article_id    uuid,
  article_slug  text,
  article_title text,
  actor_id      uuid references public.profiles (id) on delete set null,
  actor_name    text,
  threshold     int,
  dedupe_key    text not null,
  read_at       timestamptz,
  created_at    timestamptz not null default now(),
  unique (recipient_id, dedupe_key)
);

-- Turn the confusing 42703 above into an actionable message if the name is ever
-- taken by something else.
do $$ begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'newsroom_notifications'
      and column_name = 'recipient_id'
  ) then
    raise exception
      'public.newsroom_notifications already exists and is not the newsroom table (no recipient_id column). Rename or drop that table, then re-run this migration.';
  end if;
end $$;

create index if not exists newsroom_notifications_recipient_idx
  on public.newsroom_notifications (recipient_id, created_at desc);
create index if not exists newsroom_notifications_unread_idx
  on public.newsroom_notifications (recipient_id) where read_at is null;
create index if not exists newsroom_notifications_article_idx
  on public.newsroom_notifications (article_id);

-- ----------------------------------------------------------------------------
-- Thresholds — tune these two functions to change what counts as "significant".
-- ----------------------------------------------------------------------------
create or replace function public.newsroom_view_milestones()
returns int[] language sql immutable as $$
  select array[100, 500, 1000, 5000, 10000, 50000, 100000];
$$;

create or replace function public.newsroom_reaction_milestones()
returns int[] language sql immutable as $$
  select array[1, 5, 10, 25, 50, 100, 250, 500, 1000];
$$;

-- Highest threshold strictly above p_old and at or below p_new, else null.
-- Using the highest keeps a single notification when a count jumps several tiers.
create or replace function public.newsroom_crossed_milestone(
  p_old int,
  p_new int,
  p_thresholds int[]
)
returns int language sql immutable as $$
  select max(t)
  from unnest(p_thresholds) as t
  where t > coalesce(p_old, 0) and t <= coalesce(p_new, 0);
$$;

-- ----------------------------------------------------------------------------
-- Fan-out helper. SECURITY DEFINER so triggers can write past RLS (clients may
-- only ever read their own rows).
-- ----------------------------------------------------------------------------
create or replace function public.emit_newsroom_notification(
  p_article_id uuid,
  p_slug       text,
  p_title      text,
  p_author_id  uuid,
  p_type       public.newsroom_notification_type,
  p_threshold  int default null
)
returns void language plpgsql security definer set search_path = public as $$
declare
  v_actor      uuid := auth.uid();
  v_actor_name text;
  v_dedupe     text;
begin
  v_dedupe := p_type::text || ':' || coalesce(p_article_id::text, 'unknown')
    || case when p_threshold is null then '' else ':' || p_threshold::text end;

  if v_actor is not null then
    select coalesce(display_name, full_name) into v_actor_name
      from public.profiles where id = v_actor;
  end if;

  insert into public.newsroom_notifications (
    recipient_id, type, article_id, article_slug, article_title,
    actor_id, actor_name, threshold, dedupe_key
  )
  select
    r.id, p_type, p_article_id, p_slug, p_title,
    v_actor, v_actor_name, p_threshold, v_dedupe
  from (
    -- Selected through profiles rather than taken at face value: deleting a
    -- user cascades profiles -> articles -> the delete trigger below, and the
    -- author row is already gone by then. Skipping it keeps the FK satisfied.
    select id from public.profiles where id = p_author_id
    union
    select id from public.profiles where role = 'admin'
  ) r
  -- Never notify whoever triggered the event (visitor-driven events have no actor).
  where v_actor is null or r.id <> v_actor
  on conflict (recipient_id, dedupe_key) do nothing;
end $$;

-- ----------------------------------------------------------------------------
-- Triggers
-- ----------------------------------------------------------------------------

-- Publish: only the transition into 'published'. Re-saving a published article
-- (an edit) leaves status untouched and therefore notifies nobody.
create or replace function public.newsroom_notify_article_published()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status <> 'published' then
    return null;
  end if;
  if tg_op = 'UPDATE' and old.status = 'published' then
    return null;
  end if;

  perform public.emit_newsroom_notification(
    new.id, new.slug, new.title, new.author_id, 'article_published'
  );
  return null;
end $$;

drop trigger if exists trg_newsroom_notify_published on public.articles;
create trigger trg_newsroom_notify_published
  after insert or update of status on public.articles
  for each row execute function public.newsroom_notify_article_published();

-- Delete: drop the article's now-dangling notifications, then post the notice.
create or replace function public.newsroom_notify_article_deleted()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  delete from public.newsroom_notifications where article_id = old.id;

  perform public.emit_newsroom_notification(
    old.id, old.slug, old.title, old.author_id, 'article_deleted'
  );
  return null;
end $$;

drop trigger if exists trg_newsroom_notify_deleted on public.articles;
create trigger trg_newsroom_notify_deleted
  after delete on public.articles
  for each row execute function public.newsroom_notify_article_deleted();

-- Views: record_article_view() bumps view_count one at a time.
create or replace function public.newsroom_notify_article_views()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_threshold int;
begin
  v_threshold := public.newsroom_crossed_milestone(
    old.view_count, new.view_count, public.newsroom_view_milestones()
  );
  if v_threshold is null then
    return null;
  end if;

  perform public.emit_newsroom_notification(
    new.id, new.slug, new.title, new.author_id, 'views_milestone', v_threshold
  );
  return null;
end $$;

drop trigger if exists trg_newsroom_notify_views on public.articles;
create trigger trg_newsroom_notify_views
  after update of view_count on public.articles
  for each row execute function public.newsroom_notify_article_views();

-- Hearts / claps: toggle_heart() and toggle_clap() insert one row per visitor,
-- so the new total is the previous count + 1.
create or replace function public.newsroom_notify_article_hearts()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_count     int;
  v_threshold int;
  v_article   public.articles;
begin
  select count(*) into v_count
    from public.article_reactions where article_id = new.article_id;

  v_threshold := public.newsroom_crossed_milestone(
    v_count - 1, v_count, public.newsroom_reaction_milestones()
  );
  if v_threshold is null then
    return null;
  end if;

  select * into v_article from public.articles where id = new.article_id;
  if v_article.id is null then
    return null;
  end if;

  perform public.emit_newsroom_notification(
    v_article.id, v_article.slug, v_article.title, v_article.author_id,
    'hearts_milestone', v_threshold
  );
  return null;
end $$;

drop trigger if exists trg_newsroom_reactions_notify on public.article_reactions;
create trigger trg_newsroom_reactions_notify
  after insert on public.article_reactions
  for each row execute function public.newsroom_notify_article_hearts();

create or replace function public.newsroom_notify_article_claps()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_count     int;
  v_threshold int;
  v_article   public.articles;
begin
  select count(*) into v_count
    from public.article_claps where article_id = new.article_id;

  v_threshold := public.newsroom_crossed_milestone(
    v_count - 1, v_count, public.newsroom_reaction_milestones()
  );
  if v_threshold is null then
    return null;
  end if;

  select * into v_article from public.articles where id = new.article_id;
  if v_article.id is null then
    return null;
  end if;

  perform public.emit_newsroom_notification(
    v_article.id, v_article.slug, v_article.title, v_article.author_id,
    'claps_milestone', v_threshold
  );
  return null;
end $$;

drop trigger if exists trg_newsroom_claps_notify on public.article_claps;
create trigger trg_newsroom_claps_notify
  after insert on public.article_claps
  for each row execute function public.newsroom_notify_article_claps();

-- ----------------------------------------------------------------------------
-- RLS: recipients read their own rows. All writes go through the RPCs below so
-- read_at is the only field a client can ever change.
-- ----------------------------------------------------------------------------
alter table public.newsroom_notifications enable row level security;

drop policy if exists newsroom_notifications_select_own on public.newsroom_notifications;
create policy newsroom_notifications_select_own on public.newsroom_notifications for select
  using (recipient_id = auth.uid());

create or replace function public.mark_newsroom_notification_read(p_id uuid)
returns void language sql security definer set search_path = public as $$
  update public.newsroom_notifications
    set read_at = coalesce(read_at, now())
    where id = p_id and recipient_id = auth.uid();
$$;

create or replace function public.mark_all_newsroom_notifications_read()
returns int language plpgsql security definer set search_path = public as $$
declare
  v_updated int;
begin
  update public.newsroom_notifications
    set read_at = now()
    where recipient_id = auth.uid() and read_at is null;
  get diagnostics v_updated = row_count;
  return v_updated;
end $$;

create or replace function public.dismiss_newsroom_notification(p_id uuid)
returns void language sql security definer set search_path = public as $$
  delete from public.newsroom_notifications
    where id = p_id and recipient_id = auth.uid();
$$;

grant execute on function public.mark_newsroom_notification_read(uuid)      to authenticated;
grant execute on function public.mark_all_newsroom_notifications_read()     to authenticated;
grant execute on function public.dismiss_newsroom_notification(uuid)        to authenticated;

-- Realtime: lets the bell update without polling. Harmless if the publication
-- already carries the table (or if Realtime is disabled on the project — the
-- client falls back to polling either way).
do $$ begin
  alter publication supabase_realtime add table public.newsroom_notifications;
exception
  when duplicate_object then null;
  when undefined_object then null;
end $$;


-- Source: migrations/20260731090000_manual_comment_translations.sql
-- Hand-authored comment translations, mirroring the article translation model
-- introduced in 20260727200000_manual_article_translations.sql.
--
-- Only hand-authored rows are stored here. Readers may also get an on-the-fly
-- translation from the Chromium built-in Translator API, but that runs
-- on-device in the reader's browser and its output is deliberately never
-- persisted — a stored translation is always something a human wrote.

-- 'manual' becomes a valid provider alongside the historical machine values,
-- which are kept so any existing cached rows stay valid.
alter table public.comment_translations
  drop constraint if exists comment_translations_provider_check;

alter table public.comment_translations
  add constraint comment_translations_provider_check
  check (provider in ('google', 'deepl', 'manual'));

alter table public.comment_translations
  alter column provider set default 'manual';

-- Editors must be able to read translations on their own unpublished drafts,
-- not just published articles.
drop policy if exists comment_translations_select on public.comment_translations;
create policy comment_translations_select on public.comment_translations
  for select using (
    exists (
      select 1
      from public.article_comments c
      join public.articles a on a.id = c.article_id
      where c.id = comment_id
        and (a.status = 'published' or a.author_id = auth.uid() or public.is_admin())
    )
  );

-- Writes come from the browser (the inline comment translation editor) rather
-- than a service-role function, so the article's author and admins need an
-- explicit policy. Visitors can post comments but never translate them.
drop policy if exists comment_translations_write on public.comment_translations;
create policy comment_translations_write on public.comment_translations
  for all using (
    exists (
      select 1
      from public.article_comments c
      join public.articles a on a.id = c.article_id
      where c.id = comment_id and (a.author_id = auth.uid() or public.is_admin())
    )
  ) with check (
    exists (
      select 1
      from public.article_comments c
      join public.articles a on a.id = c.article_id
      where c.id = comment_id and (a.author_id = auth.uid() or public.is_admin())
    )
  );


-- Source: migrations/20260829065805_harden_newsroom_authorization.sql
-- Prevent profile owners from promoting themselves through the Data API.
-- RLS controls which rows may be changed; column grants control which fields.
revoke insert, update, delete on table public.profiles from anon, authenticated;
grant select on table public.profiles to anon, authenticated;
grant insert (id, full_name, display_name, bio, avatar_url)
  on table public.profiles to authenticated;
grant update (full_name, display_name, bio, avatar_url)
  on table public.profiles to authenticated;

drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to anon, authenticated
  using (true);

drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (
    id = (select auth.uid())
    or (select public.is_admin())
  )
  with check (
    id = (select auth.uid())
    or (select public.is_admin())
  );

drop policy if exists profiles_insert_self on public.profiles;
create policy profiles_insert_self on public.profiles
  for insert to authenticated
  with check (
    id = (select auth.uid())
    and role = 'author'::public.user_role
  );

-- Trigger helpers are internal entry points. PostgreSQL grants function
-- execution to PUBLIC by default, so revoke it explicitly for every role that
-- can reach the Data API.
revoke execute on function public.emit_newsroom_notification(
  uuid, text, text, uuid, public.newsroom_notification_type, integer
) from public, anon, authenticated;

revoke execute on function public.newsroom_notify_article_published()
  from public, anon, authenticated;
revoke execute on function public.newsroom_notify_article_deleted()
  from public, anon, authenticated;
revoke execute on function public.newsroom_notify_article_views()
  from public, anon, authenticated;
revoke execute on function public.newsroom_notify_article_hearts()
  from public, anon, authenticated;
revoke execute on function public.newsroom_notify_article_claps()
  from public, anon, authenticated;

-- These three RPCs authenticate and scope writes with auth.uid(). Keep them
-- available to signed-in users only, rather than inheriting PUBLIC execute.
revoke execute on function public.mark_newsroom_notification_read(uuid)
  from public, anon, authenticated;
revoke execute on function public.mark_all_newsroom_notifications_read()
  from public, anon, authenticated;
revoke execute on function public.dismiss_newsroom_notification(uuid)
  from public, anon, authenticated;

grant execute on function public.mark_newsroom_notification_read(uuid)
  to authenticated;
grant execute on function public.mark_all_newsroom_notifications_read()
  to authenticated;
grant execute on function public.dismiss_newsroom_notification(uuid)
  to authenticated;


-- Source: migrations/20260924121129_chatbot_device_sync.sql
begin;

-- Optional, browser-encrypted visitor transcripts. No relationship to the
-- invite-only newsroom accounts. Only the capability-checking server endpoint
-- can reach these rows; neither anon nor authenticated receives any grant.
create table public.chat_history_vaults (
  id text primary key check (id ~ '^[a-f0-9]{64}$'),
  revision bigint not null check (revision between 1 and 9007199254740991),
  payload jsonb not null check (
    jsonb_typeof(payload) = 'object'
    and payload ?& array['version', 'iv', 'data']
    and jsonb_typeof(payload->'version') = 'number'
    and jsonb_typeof(payload->'iv') = 'string'
    and jsonb_typeof(payload->'data') = 'string'
    and payload->>'version' = '1'
    and payload->>'iv' ~ '^[A-Za-z0-9_-]{16}$'
    and length(payload->>'data') between 24 and 1500000
    and octet_length(payload::text) <= 1501000
  ),
  updated_at timestamptz not null default now()
);

alter table public.chat_history_vaults enable row level security;
revoke all on public.chat_history_vaults from public, anon, authenticated;
grant select, insert, update, delete on public.chat_history_vaults to service_role;
comment on table public.chat_history_vaults is 'Encrypted opt-in chat history. Pairing/encryption secrets are never stored here. Access only through chat-history function.';

commit;


-- Source: migrations/20261008080411_secure_article_saves_and_drafts.sql
-- Account drafts and gallery edits share one transaction. RPCs keep RLS enabled.
alter table public.articles add column if not exists last_save_id uuid;
alter table public.articles add column if not exists cover_storage_path text;
alter table public.articles add column if not exists cover_alt_storage_path text;

-- Public bylines must never be inferred from private account email addresses.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, full_name, display_name, avatar_url)
  values (new.id, nullif(new.raw_user_meta_data->>'full_name', ''),
    coalesce(nullif(new.raw_user_meta_data->>'display_name', ''), 'Author'),
    new.raw_user_meta_data->>'avatar_url') on conflict (id) do nothing;
  return new;
end $$;
revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- Repair only the historical fallback, preserving explicitly supplied names.
update public.profiles p set full_name = null
from auth.users u where p.id = u.id and p.full_name = u.email
  and nullif(u.raw_user_meta_data->>'full_name', '') is null;
update public.profiles p set display_name = 'Author'
from auth.users u where p.id = u.id and p.display_name = split_part(u.email, '@', 1)
  and nullif(u.raw_user_meta_data->>'display_name', '') is null;

-- A tombstone survives failed/lost cleanup responses, and prevents a later save
-- from reattaching an object that a cleanup worker may already be deleting.
create table if not exists public.article_storage_cleanup (
  path text primary key,
  source_url text not null,
  owner_id uuid not null,
  created_at timestamptz not null default now(),
  processed_at timestamptz
);
create index if not exists article_storage_cleanup_pending_idx
  on public.article_storage_cleanup (created_at) where processed_at is null;
create index if not exists article_storage_cleanup_owner_pending_idx
  on public.article_storage_cleanup (owner_id, created_at) where processed_at is null;
alter table public.article_storage_cleanup enable row level security;
revoke all on public.article_storage_cleanup from public, anon, authenticated;
grant select on public.article_storage_cleanup to authenticated;
grant all on public.article_storage_cleanup to service_role;
drop policy if exists article_storage_cleanup_select on public.article_storage_cleanup;
create policy article_storage_cleanup_select on public.article_storage_cleanup
  for select to authenticated using (owner_id = (select auth.uid()) or (select public.is_admin()));

create or replace function public.article_storage_path_from_url(p_url text)
returns text language sql immutable set search_path = '' as $$
  select substring(p_url from '^https://[^/]+/storage/v1/object/public/article-media/([a-f0-9-]{36}/[^?#]+)$');
$$;
revoke execute on function public.article_storage_path_from_url(text) from public, anon;
grant execute on function public.article_storage_path_from_url(text) to authenticated, service_role;

create index if not exists article_media_storage_path_idx on public.article_media (storage_path);
create index if not exists articles_cover_storage_path_idx on public.articles (cover_storage_path);
create index if not exists articles_cover_alt_storage_path_idx on public.articles (cover_alt_storage_path);
create index if not exists articles_cover_url_path_idx on public.articles (public.article_storage_path_from_url(cover_image_url));
create index if not exists articles_cover_alt_url_path_idx on public.articles (public.article_storage_path_from_url(cover_image_alt_url));

create or replace function public.article_storage_path_referenced(p_path text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.article_media where storage_path = p_path)
    or exists (select 1 from public.articles where cover_storage_path = p_path
      or cover_alt_storage_path = p_path
      or public.article_storage_path_from_url(cover_image_url) = p_path
      or public.article_storage_path_from_url(cover_image_alt_url) = p_path);
$$;
revoke execute on function public.article_storage_path_referenced(text) from public, anon, authenticated;

create or replace function public.queue_article_storage_cleanup(p_path text, p_url text, p_author uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_owner uuid;
begin
  if p_author is null or p_path is null or p_url is null or p_path ~ '(^|/)\.\.(/|$)' then return; end if;
  begin v_owner := split_part(p_path, '/', 1)::uuid;
  exception when invalid_text_representation then return; end;
  -- Legacy metadata is untrusted. Never let an author enqueue another account's
  -- object for deletion by the service worker.
  if v_owner <> p_author and v_owner is distinct from auth.uid() and not public.is_admin() then return; end if;
  insert into public.article_storage_cleanup(path, source_url, owner_id)
    values (p_path, p_url, v_owner) on conflict (path) do nothing;
end $$;
revoke execute on function public.queue_article_storage_cleanup(text, text, uuid) from public, anon, authenticated;

create or replace function public.queue_removed_article_storage()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_author uuid;
begin
  if tg_table_name = 'article_media' then
    select author_id into v_author from public.articles where id = old.article_id;
    if tg_op = 'DELETE' or new.storage_path is distinct from old.storage_path then
      perform public.queue_article_storage_cleanup(old.storage_path, old.url, v_author);
    end if;
  else
    if tg_op = 'DELETE' or new.cover_image_url is distinct from old.cover_image_url then
      perform public.queue_article_storage_cleanup(coalesce(old.cover_storage_path,
        public.article_storage_path_from_url(old.cover_image_url)), old.cover_image_url, old.author_id);
    end if;
    if tg_op = 'DELETE' or new.cover_image_alt_url is distinct from old.cover_image_alt_url then
      perform public.queue_article_storage_cleanup(coalesce(old.cover_alt_storage_path,
        public.article_storage_path_from_url(old.cover_image_alt_url)), old.cover_image_alt_url, old.author_id);
    end if;
    -- BEFORE DELETE still has the parent row, unlike cascading child deletes.
    if tg_op = 'DELETE' then
      perform public.queue_article_storage_cleanup(m.storage_path, m.url, old.author_id)
        from public.article_media m where m.article_id = old.id;
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
revoke execute on function public.queue_removed_article_storage() from public, anon, authenticated;
drop trigger if exists trg_article_storage_cleanup on public.articles;
create trigger trg_article_storage_cleanup before update or delete on public.articles
  for each row execute function public.queue_removed_article_storage();
drop trigger if exists trg_media_storage_cleanup on public.article_media;
create trigger trg_media_storage_cleanup before update or delete on public.article_media
  for each row execute function public.queue_removed_article_storage();

create or replace function public.pending_article_storage_cleanup()
returns table(path text, source_url text) language sql security definer set search_path = '' as $$
  select q.path, q.source_url from public.article_storage_cleanup q
  where q.processed_at is null
    and (auth.role() = 'service_role' or (auth.uid() is not null
      and (q.owner_id = auth.uid() or public.is_admin())))
    and not public.article_storage_path_referenced(q.path)
  order by q.created_at limit 100;
$$;
create or replace function public.finish_article_storage_cleanup(p_paths text[])
returns void language sql security definer set search_path = '' as $$
  update public.article_storage_cleanup q set processed_at = now()
  where q.path = any(p_paths) and q.processed_at is null
    and (auth.role() = 'service_role' or (auth.uid() is not null
      and (q.owner_id = auth.uid() or public.is_admin())))
    and not public.article_storage_path_referenced(q.path);
$$;
revoke execute on function public.pending_article_storage_cleanup(), public.finish_article_storage_cleanup(text[])
  from public, anon, authenticated;
grant execute on function public.pending_article_storage_cleanup(), public.finish_article_storage_cleanup(text[])
  to authenticated, service_role;

-- Serialize caps against the parent, including direct Data API writes/updates.
create or replace function public.enforce_media_limits()
returns trigger language plpgsql set search_path = '' as $$
declare v_count integer;
begin
  perform 1 from public.articles where id = new.article_id for update;
  new.storage_path := coalesce(new.storage_path, public.article_storage_path_from_url(new.url));
  if auth.uid() is not null and new.storage_path is not null
    and (tg_op = 'INSERT' or new.storage_path is distinct from old.storage_path) then
    if (split_part(new.storage_path, '/', 1) <> auth.uid()::text and not public.is_admin())
      or new.storage_path ~ '(^|/)\.\.(/|$)'
      or exists (select 1 from public.article_storage_cleanup where path = new.storage_path) then
      raise insufficient_privilege using message = 'Invalid or retired media reference';
    end if;
  end if;
  select count(*) into v_count from public.article_media
    where article_id = new.article_id and kind = new.kind and id <> new.id;
  if (new.kind = 'image' and v_count >= 10) or (new.kind = 'video' and v_count >= 2) then
    raise exception 'Maximum of 10 images and 2 videos per article';
  end if;
  return new;
end $$;
drop trigger if exists trg_enforce_media_limits on public.article_media;
create trigger trg_enforce_media_limits before insert or update on public.article_media
  for each row execute function public.enforce_media_limits();

create or replace function public.validate_article_cover_paths()
returns trigger language plpgsql set search_path = '' as $$
declare v_path text;
begin
  if auth.uid() is null then return new; end if;
  new.cover_storage_path := coalesce(new.cover_storage_path, public.article_storage_path_from_url(new.cover_image_url));
  new.cover_alt_storage_path := coalesce(new.cover_alt_storage_path, public.article_storage_path_from_url(new.cover_image_alt_url));
  foreach v_path in array array[new.cover_storage_path, new.cover_alt_storage_path] loop
    if v_path is not null and (tg_op = 'INSERT' or (v_path is distinct from old.cover_storage_path
      and v_path is distinct from old.cover_alt_storage_path
      and v_path is distinct from public.article_storage_path_from_url(old.cover_image_url)
      and v_path is distinct from public.article_storage_path_from_url(old.cover_image_alt_url))) then
      if (split_part(v_path, '/', 1) <> auth.uid()::text and not public.is_admin())
        or v_path ~ '(^|/)\.\.(/|$)'
        or exists (select 1 from public.article_storage_cleanup where path = v_path) then
        raise insufficient_privilege using message = 'Invalid or retired cover reference';
      end if;
    end if;
  end loop;
  return new;
end $$;
revoke execute on function public.validate_article_cover_paths() from public, anon, authenticated;
drop trigger if exists trg_validate_article_cover_paths on public.articles;
create trigger trg_validate_article_cover_paths before insert or update on public.articles
  for each row execute function public.validate_article_cover_paths();

create or replace function public.save_article(
  p_id uuid, p_save_id uuid, p_payload jsonb, p_media jsonb,
  p_expected_updated_at timestamptz default null
) returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  v_article public.articles%rowtype;
  v_row jsonb;
  v_status public.article_status;
  v_path text;
  v_cover_path text;
  v_alt_path text;
begin
  if auth.uid() is null then raise insufficient_privilege using message = 'Sign in to save an article'; end if;
  select * into v_article from public.articles where id = p_id for update;
  if not found or (v_article.author_id <> auth.uid() and not public.is_admin()) then
    raise insufficient_privilege using message = 'Article not found or not editable';
  end if;
  if p_save_id is null then raise exception 'Save identity required'; end if;
  -- A response can be lost after commit. The same explicit retry is a no-op.
  if v_article.last_save_id = p_save_id then
    return jsonb_build_object('id', p_id, 'slug', v_article.slug, 'updated_at', v_article.updated_at);
  end if;
  if p_expected_updated_at is not null and v_article.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'This article changed in another editor. Reload before saving.';
  end if;
  if jsonb_typeof(p_payload) is distinct from 'object' or jsonb_typeof(p_media) is distinct from 'array' then
    raise exception 'Invalid article payload';
  end if;
  v_status := coalesce((p_payload->>'status')::public.article_status, v_article.status);
  if v_article.status = 'published' and v_status = 'draft' then
    raise exception 'A published article cannot be replaced by a draft';
  end if;
  if v_status = 'published' and (length(btrim(coalesce(p_payload->>'title', ''))) = 0
    or length(btrim(regexp_replace(coalesce(p_payload->>'content_html', ''), '<[^>]*>', '', 'g'))) = 0) then
    raise exception 'A title and article body are required to publish';
  end if;
  if jsonb_array_length(p_media) > 12
    or (select count(*) from jsonb_array_elements(p_media) m where m->>'kind' = 'image') > 10
    or (select count(*) from jsonb_array_elements(p_media) m where m->>'kind' = 'video') > 2
    or (select count(distinct m->>'id') from jsonb_array_elements(p_media) m) <> jsonb_array_length(p_media) then
    raise exception 'Invalid gallery or media limit exceeded';
  end if;
  -- New file references must belong to this account (admins may manage others).
  -- Retained references may have been uploaded by an admin editing the article.
  for v_row in select value from jsonb_array_elements(p_media) loop
    v_path := nullif(v_row->>'storage_path', '');
    if v_path is not null and not exists (select 1 from public.article_media
      where article_id = p_id and id = (v_row->>'id')::uuid and storage_path = v_path) then
      if (split_part(v_path, '/', 1) <> auth.uid()::text and not public.is_admin())
        or v_path ~ '(^|/)\.\.(/|$)'
        or not exists (select 1 from storage.objects where bucket_id = 'article-media' and name = v_path)
        or exists (select 1 from public.article_storage_cleanup where path = v_path) then
        raise insufficient_privilege using message = 'Invalid or retired media reference';
      end if;
    end if;
  end loop;
  v_cover_path := nullif(p_payload->>'cover_storage_path', '');
  v_alt_path := nullif(p_payload->>'cover_alt_storage_path', '');
  foreach v_path in array array[v_cover_path, v_alt_path] loop
    if v_path is not null and v_path is distinct from v_article.cover_storage_path
      and v_path is distinct from v_article.cover_alt_storage_path
      and v_path is distinct from public.article_storage_path_from_url(v_article.cover_image_url)
      and v_path is distinct from public.article_storage_path_from_url(v_article.cover_image_alt_url) then
      if (split_part(v_path, '/', 1) <> auth.uid()::text and not public.is_admin())
        or v_path ~ '(^|/)\.\.(/|$)'
        or not exists (select 1 from storage.objects where bucket_id = 'article-media' and name = v_path)
        or exists (select 1 from public.article_storage_cleanup where path = v_path) then
        raise insufficient_privilege using message = 'Invalid or retired cover reference';
      end if;
    end if;
  end loop;

  delete from public.article_media where article_id = p_id
    and id not in (select (m->>'id')::uuid from jsonb_array_elements(p_media) m);
  for v_row in select value from jsonb_array_elements(p_media) loop
    if exists (select 1 from public.article_media where article_id = p_id and id = (v_row->>'id')::uuid) then
      update public.article_media set kind = (v_row->>'kind')::public.media_kind,
        url = v_row->>'url', storage_path = nullif(v_row->>'storage_path', ''),
        poster_url = nullif(v_row->>'poster_url', ''), info = nullif(v_row->>'info', ''),
        position = (v_row->>'position')::integer
      where article_id = p_id and id = (v_row->>'id')::uuid;
    else
      insert into public.article_media(id, article_id, kind, url, storage_path, poster_url, info, position)
      values ((v_row->>'id')::uuid, p_id, (v_row->>'kind')::public.media_kind, v_row->>'url',
        nullif(v_row->>'storage_path', ''), nullif(v_row->>'poster_url', ''), nullif(v_row->>'info', ''),
        (v_row->>'position')::integer);
    end if;
  end loop;
  update public.articles set
    title = coalesce(p_payload->>'title', ''), subtitle = nullif(p_payload->>'subtitle', ''),
    author_name = nullif(p_payload->>'author_name', ''), content_html = coalesce(p_payload->>'content_html', ''),
    content_json = nullif(p_payload->'content_json', 'null'::jsonb),
    cover_image_url = nullif(p_payload->>'cover_image_url', ''),
    cover_image_alt_url = nullif(p_payload->>'cover_image_alt_url', ''),
    cover_storage_path = v_cover_path, cover_alt_storage_path = v_alt_path,
    cover_info = nullif(p_payload->>'cover_info', ''),
    cover_comparison = nullif(p_payload->'cover_comparison', 'null'::jsonb),
    language = coalesce(nullif(p_payload->>'language', ''), 'vi'),
    category = coalesce(nullif(p_payload->>'category', ''), 'general'),
    article_date = nullif(p_payload->>'article_date', '')::date,
    article_time = nullif(p_payload->>'article_time', '')::time,
    read_minutes = greatest(1, coalesce((p_payload->>'read_minutes')::integer, 1)),
    sources = coalesce(p_payload->'sources', '[]'::jsonb), status = v_status,
    published_at = case when v_status = 'published' then coalesce(v_article.published_at, now()) else v_article.published_at end,
    last_save_id = p_save_id
  where id = p_id returning * into v_article;
  return jsonb_build_object('id', p_id, 'slug', v_article.slug, 'updated_at', v_article.updated_at);
end $$;
revoke execute on function public.save_article(uuid, uuid, jsonb, jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.save_article(uuid, uuid, jsonb, jsonb, timestamptz) to authenticated;

-- Public download URLs remain compatible. Anonymous bucket listings must not
-- reveal filenames of unpublished or unattached account uploads.
drop policy if exists storage_public_read on storage.objects;
create policy storage_public_read on storage.objects for select to anon, authenticated
  using (bucket_id = 'avatars' or (bucket_id = 'article-media' and (
    split_part(name, '/', 1) = (select auth.uid())::text
    or (select public.is_admin())
    or exists (select 1 from public.article_media m join public.articles a on a.id = m.article_id
      where m.storage_path = storage.objects.name and a.status = 'published')
    or exists (select 1 from public.articles a where a.status = 'published' and (
      a.cover_storage_path = storage.objects.name or a.cover_alt_storage_path = storage.objects.name
      or public.article_storage_path_from_url(a.cover_image_url) = storage.objects.name
      or public.article_storage_path_from_url(a.cover_image_alt_url) = storage.objects.name))
  )));
-- This URL parser contains no data and is used by the anonymous storage policy.
grant execute on function public.article_storage_path_from_url(text) to anon;

-- Pin existing newsroom helper paths without changing their behavior.
do $$ declare helper record; begin
  for helper in select proname, pg_get_function_identity_arguments(oid) as arguments
    from pg_proc where pronamespace = 'public'::regnamespace and proname in (
      'client_ip', 'client_ip_hash', 'touch_updated_at', 'touch_articles_updated_at',
      'newsroom_view_milestones', 'newsroom_reaction_milestones', 'newsroom_crossed_milestone'
    ) loop
    execute format('alter function public.%I(%s) set search_path = public, pg_temp', helper.proname, helper.arguments);
  end loop;
end $$;

-- Anonymous feedback must obey the same published-only visibility as comments.
create or replace function public.get_hearts(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip    text := public.client_ip_hash();
  v_count int;
  v_liked boolean;
begin
  if not exists (select 1 from public.articles where id = p_article and status = 'published') then
    raise exception 'article not found';
  end if;
  select count(*) into v_count from public.article_reactions where article_id = p_article;
  select exists (
    select 1 from public.article_reactions where article_id = p_article and ip_hash = v_ip
  ) into v_liked;
  return json_build_object('liked', v_liked, 'count', v_count);
end $$;

-- Toggle this visitor's heart on/off; returns the new state + count.
create or replace function public.toggle_heart(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip    text := public.client_ip_hash();
  v_liked boolean;
  v_count int;
begin
  if not exists (select 1 from public.articles where id = p_article and status = 'published') then
    raise exception 'article not found';
  end if;

  if exists (
    select 1 from public.article_reactions where article_id = p_article and ip_hash = v_ip
  ) then
    delete from public.article_reactions where article_id = p_article and ip_hash = v_ip;
    v_liked := false;
  else
    insert into public.article_reactions (article_id, ip_hash)
      values (p_article, v_ip) on conflict do nothing;
    v_liked := true;
  end if;

  select count(*) into v_count from public.article_reactions where article_id = p_article;
  return json_build_object('liked', v_liked, 'count', v_count);
end $$;

-- Current clap count + whether this visitor has already clapped.
create or replace function public.get_claps(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip      text := public.client_ip_hash();
  v_count   int;
  v_clapped boolean;
begin
  if not exists (select 1 from public.articles where id = p_article and status = 'published') then
    raise exception 'article not found';
  end if;
  select count(*) into v_count from public.article_claps where article_id = p_article;
  select exists (
    select 1 from public.article_claps where article_id = p_article and ip_hash = v_ip
  ) into v_clapped;
  return json_build_object('clapped', v_clapped, 'count', v_count);
end $$;

-- Toggle this visitor's clap on/off; returns the new state + count.
create or replace function public.toggle_clap(p_article uuid)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_ip      text := public.client_ip_hash();
  v_clapped boolean;
  v_count   int;
begin
  if not exists (select 1 from public.articles where id = p_article and status = 'published') then
    raise exception 'article not found';
  end if;

  if exists (
    select 1 from public.article_claps where article_id = p_article and ip_hash = v_ip
  ) then
    delete from public.article_claps where article_id = p_article and ip_hash = v_ip;
    v_clapped := false;
  else
    insert into public.article_claps (article_id, ip_hash)
      values (p_article, v_ip) on conflict do nothing;
    v_clapped := true;
  end if;

  select count(*) into v_count from public.article_claps where article_id = p_article;
  return json_build_object('clapped', v_clapped, 'count', v_count);
end $$;

revoke execute on function public.get_hearts(uuid), public.toggle_heart(uuid), public.get_claps(uuid), public.toggle_clap(uuid) from public, anon, authenticated;
grant execute on function public.get_hearts(uuid), public.toggle_heart(uuid), public.get_claps(uuid), public.toggle_clap(uuid) to anon, authenticated;


-- Source: migrations/20261025070642_human_live_chat.sql
-- A visitor's random capability opens only their own thread. Staff access is
-- checked against the existing, owner-controlled newsroom admin role.
begin;

create schema if not exists icue_support;
revoke all on schema icue_support from public;
grant usage on schema icue_support to anon, authenticated;

create table icue_support.conversations (
  id uuid primary key default gen_random_uuid(),
  token_hash bytea not null unique,
  locale text not null check (locale in ('vi','en','de','fr','ko','ja')),
  visitor_name text not null default '' check (char_length(visitor_name) <= 100),
  visitor_email text not null default '' check (char_length(visitor_email) <= 254),
  page_path text not null default '/' check (char_length(page_path) <= 500),
  status text not null default 'waiting' check (status in ('waiting','active','closed')),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  visitor_read_seq bigint not null default 0,
  staff_read_seq bigint not null default 0,
  visitor_typing_until timestamptz,
  staff_typing_until timestamptz
);
create index support_queue_updated_idx on icue_support.conversations(updated_at desc, id);
create index support_queue_status_idx on icue_support.conversations(status, updated_at desc);

create table icue_support.messages (
  seq bigint generated always as identity primary key,
  id uuid not null unique default gen_random_uuid(),
  conversation_id uuid not null references icue_support.conversations(id) on delete cascade,
  client_id uuid not null,
  sender text not null check (sender in ('visitor','staff')),
  sender_name text not null default '',
  content text not null check (char_length(trim(content)) between 1 and 4000),
  created_at timestamptz not null default clock_timestamp(),
  unique (conversation_id, client_id)
);
create index support_messages_thread_idx on icue_support.messages(conversation_id, seq desc);
create index support_messages_rate_idx on icue_support.messages(conversation_id, created_at desc);

create table icue_support.presence (
  staff_id uuid primary key references public.profiles(id) on delete cascade,
  available boolean not null default false,
  seen_at timestamptz not null default clock_timestamp()
);
alter table icue_support.conversations enable row level security;
alter table icue_support.messages enable row level security;
alter table icue_support.presence enable row level security;
revoke all on all tables in schema icue_support from public, anon, authenticated;
revoke all on all sequences in schema icue_support from public, anon, authenticated;

create function icue_support.health() returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('version', 1, 'server_time', clock_timestamp(),
    'available_until', (select max(s.seen_at) + interval '45 seconds'
      from icue_support.presence s join public.profiles p on p.id = s.staff_id
      where s.available and p.role = 'admin' and s.seen_at > clock_timestamp() - interval '45 seconds'));
$$;

-- A missing token never becomes an anonymous staff identity. Supplying a
-- conversation UUID is useful only to an authorized administrator.
create function icue_support.authorize(p_token text, p_id uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare v_id uuid;
begin
  if p_token is not null then
    if p_token !~ '^[a-f0-9]{64}$' then raise exception 'Conversation unavailable.' using errcode = '42501'; end if;
    select id into v_id from icue_support.conversations
      where token_hash = sha256(convert_to(p_token, 'UTF8')) and (p_id is null or id = p_id);
  elsif auth.uid() is not null and public.is_admin() then
    select id into v_id from icue_support.conversations where id = p_id;
  end if;
  if v_id is null then raise exception 'Conversation unavailable.' using errcode = '42501'; end if;
  return v_id;
end;
$$;

create function icue_support.read_chat(p_token text, p_id uuid, p_before bigint, p_mark_read boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_chat icue_support.conversations; v_messages jsonb; v_first bigint; v_latest bigint;
begin
  v_id := icue_support.authorize(p_token, p_id);
  if p_mark_read and p_before is null then
    select coalesce(max(seq), 0) into v_latest from icue_support.messages where conversation_id = v_id;
    if p_token is null then
      update icue_support.conversations set staff_read_seq = greatest(staff_read_seq, v_latest) where id = v_id;
    else
      update icue_support.conversations set visitor_read_seq = greatest(visitor_read_seq, v_latest) where id = v_id;
    end if;
  end if;
  select * into v_chat from icue_support.conversations where id = v_id;
  select coalesce(jsonb_agg(to_jsonb(m) - 'conversation_id' order by m.seq), '[]'::jsonb), min(m.seq)
    into v_messages, v_first from (
      select * from icue_support.messages where conversation_id = v_id
        and (p_before is null or seq < p_before) order by seq desc limit 50
    ) m;
  return jsonb_build_object('conversation', jsonb_build_object(
      'id', v_chat.id, 'locale', v_chat.locale, 'status', v_chat.status,
      'visitor_name', v_chat.visitor_name, 'visitor_email', v_chat.visitor_email,
      'page_path', v_chat.page_path, 'created_at', v_chat.created_at,
      'visitor_read_seq', v_chat.visitor_read_seq, 'staff_read_seq', v_chat.staff_read_seq,
      'visitor_typing_until', v_chat.visitor_typing_until, 'staff_typing_until', v_chat.staff_typing_until),
    'messages', v_messages, 'has_more', exists(select 1 from icue_support.messages where conversation_id = v_id and seq < v_first),
    'health', icue_support.health());
end;
$$;

create function icue_support.send_chat(p_client_id uuid, p_message text, p_token text, p_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_sender text; v_name text; v_existing icue_support.messages;
begin
  v_id := icue_support.authorize(p_token, p_id);
  if p_client_id is null or p_message is null or char_length(trim(p_message)) not between 1 and 4000 then
    raise exception 'Check your message.' using errcode = '22023';
  end if;
  -- Serialize writes per conversation, including retry/rate checks.
  perform 1 from icue_support.conversations where id = v_id for update;
  v_sender := case when p_token is null then 'staff' else 'visitor' end;
  select * into v_existing from icue_support.messages where conversation_id = v_id and client_id = p_client_id;
  if found then
    if v_existing.sender <> v_sender or v_existing.content <> trim(p_message) then
      raise exception 'Message identifier already used.' using errcode = '22023';
    end if;
    return icue_support.read_chat(p_token, v_id, null, true);
  end if;
  if (select count(*) from icue_support.messages where conversation_id = v_id and sender = v_sender
      and created_at > clock_timestamp() - interval '1 minute') >= 30 then
    raise exception 'Please wait before sending another message.' using errcode = 'P0001';
  end if;
  if p_token is null then
    select coalesce(nullif(trim(display_name), ''), 'ICUE') into v_name from public.profiles where id = auth.uid();
  else
    select visitor_name into v_name from icue_support.conversations where id = v_id;
  end if;
  insert into icue_support.messages(conversation_id, client_id, sender, sender_name, content)
    values (v_id, p_client_id, v_sender, coalesce(v_name, ''), trim(p_message));
  update icue_support.conversations set updated_at = clock_timestamp(),
    status = case when v_sender = 'staff' then 'active' when status = 'closed' then 'waiting' else status end,
    visitor_typing_until = case when v_sender = 'visitor' then null else visitor_typing_until end,
    staff_typing_until = case when v_sender = 'staff' then null else staff_typing_until end
    where id = v_id;
  return icue_support.read_chat(p_token, v_id, null, true);
end;
$$;

create function icue_support.open_chat(p_token text, p_client_id uuid, p_message text, p_locale text, p_name text, p_email text, p_path text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if p_token is null or p_token !~ '^[a-f0-9]{64}$'
    or p_locale is null or p_locale not in ('vi','en','de','fr','ko','ja')
    or p_name is null or char_length(p_name) > 100
    or p_email is null or char_length(p_email) > 254
    or (p_email <> '' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')
    or p_path is null or p_path !~ '^/[^?#]*$' or char_length(p_path) > 500 then
    raise exception 'Check your chat details.' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_token, 8317));
  select id into v_id from icue_support.conversations where token_hash = sha256(convert_to(p_token, 'UTF8'));
  if v_id is null then
    insert into icue_support.conversations(token_hash, locale, visitor_name, visitor_email, page_path)
      values (sha256(convert_to(p_token, 'UTF8')), p_locale, trim(p_name), lower(trim(p_email)), p_path) returning id into v_id;
  end if;
  return icue_support.send_chat(p_client_id, p_message, p_token, v_id);
end;
$$;

create function icue_support.activity(p_typing boolean, p_token text, p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  v_id := icue_support.authorize(p_token, p_id);
  if p_typing is null then return; end if;
  if p_token is null then
    update icue_support.conversations set staff_typing_until = case when p_typing then clock_timestamp() + interval '6 seconds' else null end where id = v_id;
  else
    update icue_support.conversations set visitor_typing_until = case when p_typing then clock_timestamp() + interval '6 seconds' else null end where id = v_id;
  end if;
end;
$$;

create function icue_support.set_presence(p_available boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_available is null then raise exception 'Availability required.' using errcode = '22023'; end if;
  insert into icue_support.presence(staff_id, available, seen_at) values (auth.uid(), p_available, clock_timestamp())
    on conflict (staff_id) do update set available = excluded.available, seen_at = excluded.seen_at;
  return icue_support.health();
end;
$$;

create function icue_support.inbox(p_status text, p_offset integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_rows jsonb;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('open','closed','all') or p_offset is null or p_offset not between 0 and 100000 then
    raise exception 'Invalid filter.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(to_jsonb(c) order by c.updated_at desc, c.id), '[]'::jsonb) into v_rows from (
    select c.id, c.locale, c.visitor_name, c.visitor_email, c.page_path, c.status, c.created_at, c.updated_at,
      (select content from icue_support.messages m where m.conversation_id = c.id order by seq desc limit 1) as preview,
      (select count(*) from icue_support.messages m where m.conversation_id = c.id and m.sender = 'visitor' and m.seq > c.staff_read_seq) as unread
      from icue_support.conversations c
      where p_status = 'all' or (p_status = 'open' and c.status <> 'closed') or (p_status = 'closed' and c.status = 'closed')
      order by c.updated_at desc, c.id limit 51 offset p_offset
  ) c;
  return jsonb_build_object('conversations', v_rows, 'health', icue_support.health());
end;
$$;

create function icue_support.set_status(p_id uuid, p_status text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('active','closed') then raise exception 'Invalid status.' using errcode = '22023'; end if;
  perform icue_support.authorize(null, p_id);
  update icue_support.conversations set status = p_status, updated_at = clock_timestamp(), staff_typing_until = null where id = p_id;
  return icue_support.read_chat(null, p_id, null, true);
end;
$$;

-- Exposed entrypoints are invokers; privileged implementations remain in the
-- unexposed schema. Every privileged operation checks capability or admin ID.
create function public.support_chat_health() returns jsonb language sql stable security invoker set search_path = '' as $$ select icue_support.health(); $$;
create function public.support_chat_open(p_token text, p_client_id uuid, p_message text, p_locale text, p_name text default '', p_email text default '', p_path text default '/') returns jsonb language sql security invoker set search_path = '' as $$ select icue_support.open_chat(p_token,p_client_id,p_message,p_locale,p_name,p_email,p_path); $$;
create function public.support_chat_read(p_token text default null, p_conversation_id uuid default null, p_before bigint default null, p_mark_read boolean default true) returns jsonb language sql security invoker set search_path = '' as $$ select icue_support.read_chat(p_token,p_conversation_id,p_before,p_mark_read); $$;
create function public.support_chat_send(p_client_id uuid, p_message text, p_token text default null, p_conversation_id uuid default null) returns jsonb language sql security invoker set search_path = '' as $$ select icue_support.send_chat(p_client_id,p_message,p_token,p_conversation_id); $$;
create function public.support_chat_activity(p_typing boolean, p_token text default null, p_conversation_id uuid default null) returns void language sql security invoker set search_path = '' as $$ select icue_support.activity(p_typing,p_token,p_conversation_id); $$;
create function public.support_chat_presence(p_available boolean) returns jsonb language sql security invoker set search_path = '' as $$ select icue_support.set_presence(p_available); $$;
create function public.support_chat_inbox(p_status text default 'open', p_offset integer default 0) returns jsonb language sql stable security invoker set search_path = '' as $$ select icue_support.inbox(p_status,p_offset); $$;
create function public.support_chat_status(p_conversation_id uuid, p_status text) returns jsonb language sql security invoker set search_path = '' as $$ select icue_support.set_status(p_conversation_id,p_status); $$;

revoke all on all functions in schema icue_support from public, anon, authenticated;
grant execute on function icue_support.health(), icue_support.open_chat(text,uuid,text,text,text,text,text),
  icue_support.read_chat(text,uuid,bigint,boolean), icue_support.send_chat(uuid,text,text,uuid), icue_support.activity(boolean,text,uuid) to anon, authenticated;
grant execute on function icue_support.set_presence(boolean), icue_support.inbox(text,integer), icue_support.set_status(uuid,text) to authenticated;
revoke all on function public.support_chat_health(), public.support_chat_open(text,uuid,text,text,text,text,text),
  public.support_chat_read(text,uuid,bigint,boolean), public.support_chat_send(uuid,text,text,uuid),
  public.support_chat_activity(boolean,text,uuid), public.support_chat_presence(boolean),
  public.support_chat_inbox(text,integer), public.support_chat_status(uuid,text) from public, anon, authenticated;
grant execute on function public.support_chat_health(), public.support_chat_open(text,uuid,text,text,text,text,text),
  public.support_chat_read(text,uuid,bigint,boolean), public.support_chat_send(uuid,text,text,uuid), public.support_chat_activity(boolean,text,uuid) to anon, authenticated;
grant execute on function public.support_chat_presence(boolean), public.support_chat_inbox(text,integer), public.support_chat_status(uuid,text) to authenticated;

notify pgrst, 'reload schema';
commit;


-- Source: migrations/20261025123313_chat_attendance.sql
-- General availability and the staff member handling a specific conversation
-- are separate states. Reading/replying renews a short, authorized thread lease.
begin;

alter table icue_support.conversations
  add column attending_staff_id uuid references public.profiles(id) on delete set null,
  add column attending_until timestamptz;
create index support_attending_staff_idx on icue_support.conversations(attending_staff_id);

create or replace function icue_support.read_chat(p_token text, p_id uuid, p_before bigint, p_mark_read boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_chat icue_support.conversations; v_messages jsonb; v_first bigint; v_latest bigint;
begin
  v_id := icue_support.authorize(p_token, p_id);
  if p_mark_read and p_before is null then
    select coalesce(max(seq), 0) into v_latest from icue_support.messages where conversation_id = v_id;
    if p_token is null then
      update icue_support.conversations set staff_read_seq = greatest(staff_read_seq, v_latest)
        where id = v_id and staff_read_seq < v_latest;
      -- A selected, visible inbox thread polls this read. Renew at most every
      -- 15 seconds; it also runs after a staff reply without requiring Go online.
      update icue_support.conversations set attending_staff_id = auth.uid(),
        attending_until = clock_timestamp() + interval '45 seconds'
        where id = v_id and status <> 'closed' and (
          attending_staff_id is distinct from auth.uid() or attending_until is null
          or attending_until < clock_timestamp() + interval '30 seconds');
    else
      update icue_support.conversations set visitor_read_seq = greatest(visitor_read_seq, v_latest)
        where id = v_id and visitor_read_seq < v_latest;
    end if;
  end if;
  select * into v_chat from icue_support.conversations where id = v_id;
  select coalesce(jsonb_agg(to_jsonb(m) - 'conversation_id' order by m.seq), '[]'::jsonb), min(m.seq)
    into v_messages, v_first from (
      select * from icue_support.messages where conversation_id = v_id
        and (p_before is null or seq < p_before) order by seq desc limit 50
    ) m;
  return jsonb_build_object('conversation', jsonb_build_object(
      'id', v_chat.id, 'locale', v_chat.locale, 'status', v_chat.status,
      'visitor_name', v_chat.visitor_name, 'visitor_email', v_chat.visitor_email,
      'page_path', v_chat.page_path, 'created_at', v_chat.created_at,
      'visitor_read_seq', v_chat.visitor_read_seq, 'staff_read_seq', v_chat.staff_read_seq,
      'visitor_typing_until', v_chat.visitor_typing_until, 'staff_typing_until', v_chat.staff_typing_until,
      'staff_attending_until', case when v_chat.status <> 'closed'
        and v_chat.attending_until > clock_timestamp()
        and exists(select 1 from public.profiles where id = v_chat.attending_staff_id and role = 'admin')
        then v_chat.attending_until else null end),
    'messages', v_messages, 'has_more', exists(select 1 from icue_support.messages where conversation_id = v_id and seq < v_first),
    'health', icue_support.health());
end;
$$;

create or replace function icue_support.set_status(p_id uuid, p_status text) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('active','closed') then raise exception 'Invalid status.' using errcode = '22023'; end if;
  perform icue_support.authorize(null, p_id);
  update icue_support.conversations set status = p_status, updated_at = clock_timestamp(),
    staff_typing_until = null, attending_staff_id = null, attending_until = null where id = p_id;
  return icue_support.read_chat(null, p_id, null, true);
end;
$$;

-- REPLACE preserves existing grants. Repeat the boundary explicitly so fresh
-- and upgraded installations expose only the same checked entrypoints.
revoke all on function icue_support.read_chat(text,uuid,bigint,boolean) from public, anon, authenticated;
grant execute on function icue_support.read_chat(text,uuid,bigint,boolean) to anon, authenticated;
revoke all on function icue_support.set_status(uuid,text) from public, anon, authenticated;
grant execute on function icue_support.set_status(uuid,text) to authenticated;

notify pgrst, 'reload schema';
commit;


-- Source: migrations/20261025130803_client_chat_presence.sql
-- Visitor presence is scoped to a chat window. Sequence numbers protect
-- against an old heartbeat arriving after a close; multiple tabs stay separate.
begin;

create table icue_support.visitor_connections (
  conversation_id uuid not null references icue_support.conversations(id) on delete cascade,
  connection_id uuid not null,
  sequence bigint not null check (sequence between 1 and 9007199254740991),
  state text not null check (state in ('active','away','left')),
  seen_at timestamptz not null default clock_timestamp(),
  primary key (conversation_id,connection_id)
);
create index support_visitor_seen_idx on icue_support.visitor_connections(conversation_id,seen_at desc);
alter table icue_support.visitor_connections enable row level security;
revoke all on icue_support.visitor_connections from public,anon,authenticated;

-- Only checked read/inbox implementations call this helper; it is not an API.
create function icue_support.visitor_state(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('visitor_status',
    case when active_until>clock_timestamp() then 'active'
      when away_until>clock_timestamp() then 'away'
      when last_seen is null then 'unknown'
      when last_state='left' then 'left' else 'disconnected' end,
    'visitor_seen_at',last_seen,
    'visitor_presence_until',case when active_until>clock_timestamp() then active_until
      when away_until>clock_timestamp() then away_until else null end)
  from (
    select max(seen_at+interval '45 seconds') filter(where state='active') as active_until,
      max(seen_at+interval '45 seconds') filter(where state='away') as away_until,
      max(seen_at) as last_seen,
      (array_agg(state order by seen_at desc,connection_id))[1] as last_state
    from icue_support.visitor_connections where conversation_id=p_id
  ) s;
$$;

create function icue_support.visitor_presence(p_token text,p_connection_id uuid,p_sequence bigint,p_state text) returns void
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
  if p_token is null then raise exception 'Visitor capability required.' using errcode='42501'; end if;
  v_id:=icue_support.authorize(p_token,null);
  if p_connection_id is null or p_sequence is null or p_sequence not between 1 and 9007199254740991
    or p_state is null or p_state not in ('active','away','left') then
    raise exception 'Invalid presence update.' using errcode='22023';
  end if;
  perform 1 from icue_support.conversations where id=v_id for update;
  delete from icue_support.visitor_connections where conversation_id=v_id and seen_at<clock_timestamp()-interval '1 day';
  if not exists(select 1 from icue_support.visitor_connections where conversation_id=v_id and connection_id=p_connection_id)
    and (select count(*) from icue_support.visitor_connections where conversation_id=v_id)>=20 then
    delete from icue_support.visitor_connections where conversation_id=v_id and connection_id=(
      select connection_id from icue_support.visitor_connections where conversation_id=v_id
        and seen_at<clock_timestamp()-interval '45 seconds' order by seen_at limit 1);
    if (select count(*) from icue_support.visitor_connections where conversation_id=v_id)>=20 then
      raise exception 'Too many chat windows.' using errcode='P0001';
    end if;
  end if;
  insert into icue_support.visitor_connections(conversation_id,connection_id,sequence,state,seen_at)
    values(v_id,p_connection_id,p_sequence,p_state,clock_timestamp())
    on conflict(conversation_id,connection_id) do update set sequence=excluded.sequence,state=excluded.state,seen_at=excluded.seen_at
    where excluded.sequence>icue_support.visitor_connections.sequence;
end;
$$;

create or replace function icue_support.read_chat(p_token text, p_id uuid, p_before bigint, p_mark_read boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_chat icue_support.conversations; v_messages jsonb; v_first bigint; v_latest bigint;
begin
  v_id := icue_support.authorize(p_token, p_id);
  if p_mark_read and p_before is null then
    select coalesce(max(seq), 0) into v_latest from icue_support.messages where conversation_id = v_id;
    if p_token is null then
      update icue_support.conversations set staff_read_seq = greatest(staff_read_seq, v_latest)
        where id = v_id and staff_read_seq < v_latest;
      -- A selected, visible inbox thread polls this read. Renew at most every
      -- 15 seconds; it also runs after a staff reply without requiring Go online.
      update icue_support.conversations set attending_staff_id = auth.uid(),
        attending_until = clock_timestamp() + interval '45 seconds'
        where id = v_id and status <> 'closed' and (
          attending_staff_id is distinct from auth.uid() or attending_until is null
          or attending_until < clock_timestamp() + interval '30 seconds');
    else
      update icue_support.conversations set visitor_read_seq = greatest(visitor_read_seq, v_latest)
        where id = v_id and visitor_read_seq < v_latest;
    end if;
  end if;
  select * into v_chat from icue_support.conversations where id = v_id;
  select coalesce(jsonb_agg(to_jsonb(m) - 'conversation_id' order by m.seq), '[]'::jsonb), min(m.seq)
    into v_messages, v_first from (
      select * from icue_support.messages where conversation_id = v_id
        and (p_before is null or seq < p_before) order by seq desc limit 50
    ) m;
  return jsonb_build_object('conversation', jsonb_build_object(
      'id', v_chat.id, 'locale', v_chat.locale, 'status', v_chat.status,
      'visitor_name', v_chat.visitor_name, 'visitor_email', v_chat.visitor_email,
      'page_path', v_chat.page_path, 'created_at', v_chat.created_at,
      'visitor_read_seq', v_chat.visitor_read_seq, 'staff_read_seq', v_chat.staff_read_seq,
      'visitor_typing_until', v_chat.visitor_typing_until, 'staff_typing_until', v_chat.staff_typing_until,
      'staff_attending_until', case when v_chat.status <> 'closed'
        and v_chat.attending_until > clock_timestamp()
        and exists(select 1 from public.profiles where id = v_chat.attending_staff_id and role = 'admin')
        then v_chat.attending_until else null end) || icue_support.visitor_state(v_id),
    'messages', v_messages, 'has_more', exists(select 1 from icue_support.messages where conversation_id = v_id and seq < v_first),
    'health', icue_support.health());
end;
$$;

create or replace function icue_support.inbox(p_status text, p_offset integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_rows jsonb;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('open','closed','all') or p_offset is null or p_offset not between 0 and 100000 then
    raise exception 'Invalid filter.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(to_jsonb(c) || icue_support.visitor_state(c.id) order by c.updated_at desc, c.id), '[]'::jsonb) into v_rows from (
    select c.id, c.locale, c.visitor_name, c.visitor_email, c.page_path, c.status, c.created_at, c.updated_at,
      (select content from icue_support.messages m where m.conversation_id = c.id order by seq desc limit 1) as preview,
      (select count(*) from icue_support.messages m where m.conversation_id = c.id and m.sender = 'visitor' and m.seq > c.staff_read_seq) as unread
      from icue_support.conversations c
      where p_status = 'all' or (p_status = 'open' and c.status <> 'closed') or (p_status = 'closed' and c.status = 'closed')
      order by c.updated_at desc, c.id limit 51 offset p_offset
  ) c;
  return jsonb_build_object('conversations', v_rows, 'health', icue_support.health());
end;
$$;

create function public.support_chat_visitor_presence(p_token text,p_connection_id uuid,p_sequence bigint,p_state text)
returns void language sql security invoker set search_path='' as $$
  select icue_support.visitor_presence(p_token,p_connection_id,p_sequence,p_state);
$$;
revoke all on function icue_support.visitor_state(uuid) from public,anon,authenticated;
revoke all on function icue_support.visitor_presence(text,uuid,bigint,text) from public,anon,authenticated;
grant execute on function icue_support.visitor_presence(text,uuid,bigint,text) to anon,authenticated;
revoke all on function public.support_chat_visitor_presence(text,uuid,bigint,text) from public,anon,authenticated;
grant execute on function public.support_chat_visitor_presence(text,uuid,bigint,text) to anon,authenticated;
notify pgrst,'reload schema';
commit;


-- Source: migrations/20261026150317_customer_account_role.sql
-- Public registration creates customers; staff roles remain explicitly assigned.
begin;
alter type public.user_role add value if not exists 'customer';
commit;


-- Source: migrations/20261026150318_support_files_accounts_retention.sql
begin;
grant usage on schema icue_support to service_role;
alter table public.profiles alter column role set default 'customer';
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into public.profiles(id,full_name,display_name,avatar_url,role)
 values(new.id,left(nullif(new.raw_user_meta_data->>'full_name',''),100),
 coalesce(left(nullif(new.raw_user_meta_data->>'display_name',''),100),'Customer'),
 null,'customer') on conflict(id) do nothing;
 return new;
end;
$$;
revoke all on function public.handle_new_user() from public,anon,authenticated;
create function icue_support.is_customer() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.profiles where id=auth.uid() and role='customer');
$$;
revoke all on function icue_support.is_customer() from public;
grant execute on function icue_support.is_customer() to authenticated;
-- New customer identities must not inherit any application's broad authenticated
-- policies. Existing admin/author accounts retain their current access.
do $$ declare r record; cmd text; begin
 for r in select c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where n.nspname='public' and c.relkind='r' and c.relrowsecurity loop
  foreach cmd in array array['INSERT','UPDATE','DELETE'] loop
   execute format('create policy %I on public.%I as restrictive for %s to authenticated %s',
    'customer_boundary_'||lower(cmd),r.relname,cmd,case cmd when 'INSERT' then 'with check (not (select icue_support.is_customer()))' when 'DELETE' then 'using (not (select icue_support.is_customer()))' else 'using (not (select icue_support.is_customer())) with check (not (select icue_support.is_customer()))' end);
  end loop;
  if r.relname <> all(array['profiles','articles','article_media','article_translations','article_comments','comment_translations','article_reactions','article_claps']) then
   execute format('create policy customer_boundary_select on public.%I as restrictive for select to authenticated using (not (select icue_support.is_customer()))',r.relname);
  end if;
 end loop;
end $$;
-- Restrictive INSERT/DELETE policies use only their applicable clauses.

create policy customer_storage_boundary on storage.objects as restrictive for all to authenticated
 using(not (select icue_support.is_customer())) with check(not (select icue_support.is_customer()));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
 values('support-chat','support-chat',false,10485760,array['application/pdf','image/png','image/jpeg']);
-- Existing project-wide permissive Storage policies cannot open this bucket.
create policy support_storage_private on storage.objects as restrictive for all to anon,authenticated
 using(bucket_id<>'support-chat') with check(bucket_id<>'support-chat');

alter table icue_support.conversations add column owner_id uuid references auth.users(id) on delete cascade;
alter table icue_support.conversations add column guest_expires_at timestamptz not null default (clock_timestamp()+interval '24 hours');
create index support_customer_threads_idx on icue_support.conversations(owner_id,updated_at desc) where owner_id is not null;
create index support_guest_expiry_idx on icue_support.conversations(guest_expires_at) where owner_id is null;
alter table icue_support.messages drop constraint messages_content_check;
alter table icue_support.messages add constraint messages_content_check check(char_length(content)<=4000);
create table icue_support.files(
 id uuid primary key default gen_random_uuid(), conversation_id uuid not null references icue_support.conversations(id) on delete cascade,
 client_id uuid not null, message_id uuid references icue_support.messages(id) on delete cascade,
 name text not null check(char_length(name) between 1 and 180 and name !~ E'[\\r\\n/\\\\]'),
 mime text not null check(mime in ('application/pdf','image/png','image/jpeg')),
 size integer not null check(size between 1 and 10485760), sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),
 path text not null unique, state text not null default 'reserved' check(state in ('reserved','ready')),
 created_at timestamptz not null default clock_timestamp(), unique(conversation_id,client_id)
);
create index support_files_message_idx on icue_support.files(message_id);
create index support_files_orphan_idx on icue_support.files(created_at) where message_id is null;
create table icue_support.file_cleanup(path text primary key,created_at timestamptz not null default clock_timestamp());
create table icue_support.cleanup_config(id boolean primary key default true check(id),endpoint text,key_hash bytea);
insert into icue_support.cleanup_config(id) values(true);
create function icue_support.queue_deleted_file() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into icue_support.file_cleanup(path) values(old.path) on conflict do nothing; return old; end; $$;
revoke all on function icue_support.queue_deleted_file() from public,anon,authenticated;
create trigger queue_deleted_support_file before delete on icue_support.files for each row execute function icue_support.queue_deleted_file();
alter table icue_support.files enable row level security;
alter table icue_support.file_cleanup enable row level security;
alter table icue_support.cleanup_config enable row level security;
revoke all on icue_support.files,icue_support.file_cleanup,icue_support.cleanup_config from public,anon,authenticated;

create or replace function icue_support.authorize(p_token text,p_id uuid) returns uuid
language plpgsql stable security definer set search_path='' as $$
declare v_id uuid;
begin
 if p_token is not null then
  if p_token !~ '^[a-f0-9]{64}$' then raise insufficient_privilege using message='Conversation unavailable.'; end if;
  select id into v_id from icue_support.conversations
   where token_hash=sha256(convert_to(p_token,'UTF8')) and (p_id is null or id=p_id)
   and ((owner_id is null and guest_expires_at>clock_timestamp()) or owner_id=auth.uid());
 elsif auth.uid() is not null then
  select id into v_id from icue_support.conversations where id=p_id
   and (owner_id=auth.uid() or public.is_admin())
   and (owner_id is not null or guest_expires_at>clock_timestamp());
 end if;
 if v_id is null then raise insufficient_privilege using message='Conversation unavailable.'; end if;
 return v_id;
end;
$$;
create function icue_support.staff_request(p_token text,p_id uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select p_token is null and public.is_admin() and not exists(select 1 from icue_support.conversations where id=p_id and owner_id=auth.uid());
$$;
revoke all on function icue_support.staff_request(text,uuid) from public,anon,authenticated;
create function icue_support.customer_uid() returns uuid language sql stable security definer set search_path='' as $$
 select id from auth.users where id=auth.uid() and is_anonymous is distinct from true and email is not null;
$$;
revoke all on function icue_support.customer_uid() from public,anon,authenticated;
create function icue_support.account() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',u.id,'email',u.email,'name',p.display_name,'role',p.role)
 from auth.users u join public.profiles p on p.id=u.id where u.id=icue_support.customer_uid();
$$;
create function icue_support.customer_chats() returns jsonb language plpgsql stable security definer set search_path='' as $$
begin
 if icue_support.customer_uid() is null then raise insufficient_privilege; end if;
 return jsonb_build_object('conversations',(select coalesce(jsonb_agg(to_jsonb(c) order by c.updated_at desc),'[]'::jsonb) from(
  select c.id,c.locale,c.status,c.created_at,c.updated_at,
   (select nullif(content,'') from icue_support.messages where conversation_id=c.id order by seq desc limit 1) as preview
  from icue_support.conversations c where owner_id=auth.uid() order by updated_at desc limit 100) c));
end;
$$;
create function icue_support.claim_chat(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 if icue_support.customer_uid() is null then raise insufficient_privilege; end if;
 v_id:=icue_support.authorize(p_token,null);
 perform 1 from icue_support.conversations where id=v_id for update;
 -- Recheck after the lock so cleanup/claim cannot race a guest back into life.
 perform icue_support.authorize(p_token,v_id);
 update icue_support.conversations set owner_id=auth.uid() where id=v_id and (owner_id is null or owner_id=auth.uid());
 return icue_support.read_chat(p_token,v_id,null,true);
end;
$$;
create function icue_support.prepare_chat(p_token text,p_locale text,p_name text,p_email text,p_path text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' or p_locale not in ('vi','en','de','fr','ko','ja') or p_locale is null
  or p_name is null or char_length(p_name)>100 or p_email is null or char_length(p_email)>254
  or (p_email<>'' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')
  or p_path is null or p_path !~ '^/[^?#]*$' or char_length(p_path)>500 then
  raise exception 'Check your chat details.' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_token,8317));
 select id into v_id from icue_support.conversations where token_hash=sha256(convert_to(p_token,'UTF8'));
 if v_id is null then
  insert into icue_support.conversations(token_hash,locale,visitor_name,visitor_email,page_path,owner_id)
   values(sha256(convert_to(p_token,'UTF8')),p_locale,trim(p_name),lower(trim(p_email)),p_path,icue_support.customer_uid()) returning id into v_id;
 end if;
 return icue_support.read_chat(p_token,v_id,null,true);
end;
$$;
create function icue_support.send_files(p_client_id uuid,p_message text,p_files uuid[],p_token text,p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid;v_sender text;v_staff boolean;v_name text;v_existing icue_support.messages;v_message_id uuid;v_existing_files uuid[];
begin
 v_id:=icue_support.authorize(p_token,p_id);
 perform 1 from icue_support.conversations where id=v_id for update;
 perform icue_support.authorize(p_token,v_id);
 v_staff:=icue_support.staff_request(p_token,v_id);
 v_sender:=case when v_staff then 'staff' else 'visitor' end;
 if p_client_id is null or p_message is null or p_files is null or cardinality(p_files)>5
  or char_length(trim(p_message))>4000 or (trim(p_message)='' and cardinality(p_files)=0)
  or cardinality(p_files)<>(select count(distinct x) from unnest(p_files) x) then
  raise exception 'Check your message and files.' using errcode='22023';
 end if;
 select * into v_existing from icue_support.messages where conversation_id=v_id and client_id=p_client_id;
 if found then
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into v_existing_files from icue_support.files where message_id=v_existing.id;
  if v_existing.sender<>v_sender or v_existing.content<>trim(p_message)
   or v_existing_files<>(select coalesce(array_agg(x order by x),'{}'::uuid[]) from unnest(p_files) x) then
   raise exception 'Message identifier already used.' using errcode='22023';
  end if;
  return icue_support.read_chat(p_token,v_id,null,true);
 end if;
 if (select count(*) from icue_support.messages where conversation_id=v_id and sender=v_sender and created_at>clock_timestamp()-interval '1 minute')>=30 then
  raise exception 'Please wait before sending another message.' using errcode='P0001';
 end if;
 if (select count(*) from icue_support.files where id=any(p_files) and conversation_id=v_id and state='ready' and message_id is null)<>cardinality(p_files) then
  raise insufficient_privilege using message='A file is unavailable.';
 end if;
 if v_staff then select coalesce(nullif(trim(display_name),''),'ICUE') into v_name from public.profiles where id=auth.uid();
 else select visitor_name into v_name from icue_support.conversations where id=v_id; end if;
 insert into icue_support.messages(conversation_id,client_id,sender,sender_name,content)
  values(v_id,p_client_id,v_sender,coalesce(v_name,''),trim(p_message)) returning id into v_message_id;
 update icue_support.files set message_id=v_message_id where id=any(p_files);
 update icue_support.conversations set updated_at=clock_timestamp(),
  guest_expires_at=case when v_sender='visitor' and owner_id is null then clock_timestamp()+interval '24 hours' else guest_expires_at end,
  status=case when v_staff then 'active' when status='closed' then 'waiting' else status end,
  visitor_typing_until=case when not v_staff then null else visitor_typing_until end,
  staff_typing_until=case when v_staff then null else staff_typing_until end where id=v_id;
 return icue_support.read_chat(p_token,v_id,null,true);
end;
$$;
create or replace function icue_support.send_chat(p_client_id uuid,p_message text,p_token text,p_id uuid) returns jsonb
language sql security definer set search_path='' as $$ select icue_support.send_files(p_client_id,p_message,'{}'::uuid[],p_token,p_id); $$;
create or replace function icue_support.open_chat(p_token text,p_client_id uuid,p_message text,p_locale text,p_name text,p_email text,p_path text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_chat jsonb;
begin
 v_chat:=icue_support.prepare_chat(p_token,p_locale,p_name,p_email,p_path);
 return icue_support.send_chat(p_client_id,p_message,p_token,(v_chat->'conversation'->>'id')::uuid);
end;
$$;
create or replace function icue_support.activity(p_typing boolean,p_token text,p_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 v_id:=icue_support.authorize(p_token,p_id);
 if p_typing is null then return; end if;
 if icue_support.staff_request(p_token,v_id) then
  update icue_support.conversations set staff_typing_until=case when p_typing then clock_timestamp()+interval '6 seconds' else null end where id=v_id;
 else update icue_support.conversations set visitor_typing_until=case when p_typing then clock_timestamp()+interval '6 seconds' else null end where id=v_id;
 end if;
end;
$$;
create or replace function icue_support.read_chat(p_token text, p_id uuid, p_before bigint, p_mark_read boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_chat icue_support.conversations; v_messages jsonb; v_first bigint; v_latest bigint; v_staff boolean;
begin
  v_id := icue_support.authorize(p_token, p_id);
  v_staff := icue_support.staff_request(p_token,v_id);
  if p_mark_read and p_before is null then
    select coalesce(max(seq), 0) into v_latest from icue_support.messages where conversation_id = v_id;
    if v_staff then
      update icue_support.conversations set staff_read_seq = greatest(staff_read_seq, v_latest)
        where id = v_id and staff_read_seq < v_latest;
      -- A selected, visible inbox thread polls this read. Renew at most every
      -- 15 seconds; it also runs after a staff reply without requiring Go online.
      update icue_support.conversations set attending_staff_id = auth.uid(),
        attending_until = clock_timestamp() + interval '45 seconds'
        where id = v_id and status <> 'closed' and (
          attending_staff_id is distinct from auth.uid() or attending_until is null
          or attending_until < clock_timestamp() + interval '30 seconds');
    else
      update icue_support.conversations set visitor_read_seq = greatest(visitor_read_seq, v_latest)
        where id = v_id and visitor_read_seq < v_latest;
    end if;
  end if;
  select * into v_chat from icue_support.conversations where id = v_id;
  select coalesce(jsonb_agg((to_jsonb(m) - 'conversation_id') || jsonb_build_object('attachments', (select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'name',f.name,'mime',f.mime,'size',f.size) order by f.created_at,f.id),'[]'::jsonb) from icue_support.files f where f.message_id=m.id and f.state='ready')) order by m.seq), '[]'::jsonb), min(m.seq)
    into v_messages, v_first from (
      select * from icue_support.messages where conversation_id = v_id
        and (p_before is null or seq < p_before) order by seq desc limit 50
    ) m;
  return jsonb_build_object('conversation', jsonb_build_object(
      'account_saved', v_chat.owner_id is not null, 'guest_expires_at', case when v_chat.owner_id is null then v_chat.guest_expires_at else null end,
      'id', v_chat.id, 'locale', v_chat.locale, 'status', v_chat.status,
      'visitor_name', v_chat.visitor_name, 'visitor_email', v_chat.visitor_email,
      'page_path', v_chat.page_path, 'created_at', v_chat.created_at,
      'visitor_read_seq', v_chat.visitor_read_seq, 'staff_read_seq', v_chat.staff_read_seq,
      'visitor_typing_until', v_chat.visitor_typing_until, 'staff_typing_until', v_chat.staff_typing_until,
      'staff_attending_until', case when v_chat.status <> 'closed'
        and v_chat.attending_until > clock_timestamp()
        and exists(select 1 from public.profiles where id = v_chat.attending_staff_id and role = 'admin')
        then v_chat.attending_until else null end) || icue_support.visitor_state(v_id),
    'messages', v_messages, 'has_more', exists(select 1 from icue_support.messages where conversation_id = v_id and seq < v_first),
    'health', icue_support.health());
end;
$$;

create or replace function icue_support.inbox(p_status text, p_offset integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_rows jsonb;
begin
  if auth.uid() is null or not public.is_admin() then raise exception 'Admin access required.' using errcode = '42501'; end if;
  if p_status is null or p_status not in ('open','closed','all') or p_offset is null or p_offset not between 0 and 100000 then
    raise exception 'Invalid filter.' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(to_jsonb(c) || icue_support.visitor_state(c.id) order by c.updated_at desc, c.id), '[]'::jsonb) into v_rows from (
    select c.id, c.locale, c.visitor_name, c.visitor_email, c.page_path, c.status, c.created_at, c.updated_at,
      (select content from icue_support.messages m where m.conversation_id = c.id order by seq desc limit 1) as preview,
      (select count(*) from icue_support.messages m where m.conversation_id = c.id and m.sender = 'visitor' and m.seq > c.staff_read_seq) as unread
      from icue_support.conversations c
      where (c.owner_id is not null or c.guest_expires_at>clock_timestamp()) and exists(select 1 from icue_support.messages where conversation_id=c.id)
      and (p_status = 'all' or (p_status = 'open' and c.status <> 'closed') or (p_status = 'closed' and c.status = 'closed'))
      order by c.updated_at desc, c.id limit 51 offset p_offset
  ) c;
  return jsonb_build_object('conversations', v_rows, 'health', icue_support.health());
end;
$$;

drop function public.support_chat_visitor_presence(text,uuid,bigint,text);
drop function icue_support.visitor_presence(text,uuid,bigint,text);
create function icue_support.visitor_presence(p_token text,p_connection_id uuid,p_sequence bigint,p_state text,p_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
  if p_token is null and not exists(select 1 from icue_support.conversations where id=p_id and owner_id=auth.uid()) then raise insufficient_privilege; end if;
  v_id:=icue_support.authorize(p_token,p_id);
  if p_connection_id is null or p_sequence is null or p_sequence not between 1 and 9007199254740991
    or p_state is null or p_state not in ('active','away','left') then
    raise exception 'Invalid presence update.' using errcode='22023';
  end if;
  perform 1 from icue_support.conversations where id=v_id for update;
  if p_state='active' then update icue_support.conversations set guest_expires_at=clock_timestamp()+interval '24 hours' where id=v_id and owner_id is null and guest_expires_at>clock_timestamp() and not exists(select 1 from icue_support.visitor_connections where conversation_id=v_id and connection_id=p_connection_id and sequence>=p_sequence); end if;
  delete from icue_support.visitor_connections where conversation_id=v_id and seen_at<clock_timestamp()-interval '1 day';
  if not exists(select 1 from icue_support.visitor_connections where conversation_id=v_id and connection_id=p_connection_id)
    and (select count(*) from icue_support.visitor_connections where conversation_id=v_id)>=20 then
    delete from icue_support.visitor_connections where conversation_id=v_id and connection_id=(
      select connection_id from icue_support.visitor_connections where conversation_id=v_id
        and seen_at<clock_timestamp()-interval '45 seconds' order by seen_at limit 1);
    if (select count(*) from icue_support.visitor_connections where conversation_id=v_id)>=20 then
      raise exception 'Too many chat windows.' using errcode='P0001';
    end if;
  end if;
  insert into icue_support.visitor_connections(conversation_id,connection_id,sequence,state,seen_at)
    values(v_id,p_connection_id,p_sequence,p_state,clock_timestamp())
    on conflict(conversation_id,connection_id) do update set sequence=excluded.sequence,state=excluded.state,seen_at=excluded.seen_at
    where excluded.sequence>icue_support.visitor_connections.sequence;
end;
$$;


create function icue_support.reserve_file(p_token text,p_id uuid,p_client_id uuid,p_name text,p_mime text,p_size integer,p_sha256 text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_id uuid;v_file icue_support.files;v_ext text;
begin
 v_id:=icue_support.authorize(p_token,p_id);
 perform 1 from icue_support.conversations where id=v_id for update;
 perform icue_support.authorize(p_token,v_id);
 v_ext:=lower(substring(p_name from '\.([^.]+)$'));
 if p_client_id is null or p_name is null or char_length(p_name) not between 1 and 180 or p_name ~ E'[\\r\\n/\\\\]'
  or p_size is null or p_size not between 1 and 10485760 or p_sha256 is null or p_sha256 !~ '^[a-f0-9]{64}$'
  or p_mime is null or v_ext is null or not ((p_mime='application/pdf' and v_ext='pdf') or (p_mime='image/png' and v_ext='png') or (p_mime='image/jpeg' and v_ext in ('jpg','jpeg'))) then
  raise exception 'PDF, PNG or JPEG only; maximum 10 MB per file.' using errcode='22023';
 end if;
 select * into v_file from icue_support.files where conversation_id=v_id and client_id=p_client_id;
 if found then
  if v_file.sha256<>p_sha256 or v_file.name<>p_name or v_file.mime<>p_mime or v_file.size<>p_size then raise exception 'Upload identifier already used.' using errcode='22023'; end if;
  return to_jsonb(v_file)-'conversation_id'-'sha256';
 end if;
 if (select coalesce(sum(size),0) from icue_support.files where conversation_id=v_id)+p_size>52428800
  or (select count(*) from icue_support.files where conversation_id=v_id and created_at>clock_timestamp()-interval '10 minutes')>=20 then
  raise exception 'Conversation upload limit reached.' using errcode='P0001';
 end if;
 insert into icue_support.files(conversation_id,client_id,name,mime,size,sha256,path)
  values(v_id,p_client_id,p_name,p_mime,p_size,p_sha256,v_id::text||'/'||p_client_id::text||'.'||v_ext) returning * into v_file;
 return to_jsonb(v_file)-'conversation_id'-'sha256';
end;
$$;
create function icue_support.ready_file(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare f icue_support.files;
begin
 update icue_support.files set state='ready' where id=p_id and exists(select 1 from icue_support.conversations c where c.id=conversation_id and (c.owner_id is not null or c.guest_expires_at>clock_timestamp())) returning * into f;
 if not found then raise insufficient_privilege using message='Upload expired.'; end if;
 return jsonb_build_object('id',f.id,'name',f.name,'mime',f.mime,'size',f.size,'client_id',f.client_id);
end;
$$;
create function icue_support.download_file(p_token text,p_id uuid,p_file uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid;f icue_support.files;
begin
 v_id:=icue_support.authorize(p_token,p_id);
 select * into f from icue_support.files where id=p_file and conversation_id=v_id and state='ready' and message_id is not null;
 if not found then raise insufficient_privilege using message='File unavailable.'; end if;
 return jsonb_build_object('path',f.path,'name',f.name,'mime',f.mime,'size',f.size);
end;
$$;
create function icue_support.discard_file(p_token text,p_id uuid,p_file uuid) returns void language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 v_id:=icue_support.authorize(p_token,p_id);
 perform 1 from icue_support.conversations where id=v_id for update;
 insert into icue_support.file_cleanup(path) select path from icue_support.files where id=p_file and conversation_id=v_id and message_id is null on conflict do nothing;
 delete from icue_support.files where id=p_file and conversation_id=v_id and message_id is null;
end;
$$;
create function icue_support.cleanup_batch() returns jsonb language plpgsql security definer set search_path='' as $$
declare v_ids uuid[];v_files uuid[];
begin
 select array_agg(id) into v_ids from(select id from icue_support.conversations where owner_id is null and guest_expires_at<=clock_timestamp() order by guest_expires_at limit 100 for update skip locked) c;
 insert into icue_support.file_cleanup(path) select path from icue_support.files where conversation_id=any(v_ids) on conflict do nothing;
 delete from icue_support.conversations where id=any(v_ids);
 select array_agg(id) into v_files from(select id from icue_support.files where message_id is null and created_at<clock_timestamp()-interval '1 hour' order by created_at limit 100 for update skip locked) f;
 insert into icue_support.file_cleanup(path) select path from icue_support.files where id=any(v_files) on conflict do nothing;
 delete from icue_support.files where id=any(v_files);
 return jsonb_build_object('conversations_deleted',coalesce(cardinality(v_ids),0),'paths',(select coalesce(jsonb_agg(path),'[]'::jsonb) from(select path from icue_support.file_cleanup order by created_at limit 100) q));
end;
$$;
create function icue_support.cleanup_ack(p_paths text[]) returns void language sql security definer set search_path='' as $$
 delete from icue_support.file_cleanup where path=any(p_paths);
$$;
create function icue_support.cleanup_key_valid(p_key text) returns boolean language sql stable security definer set search_path='' as $$
 select p_key is not null and sha256(convert_to(p_key,'UTF8'))=key_hash from icue_support.cleanup_config where id;
$$;
create function icue_support.dispatch_cleanup() returns bigint language plpgsql security definer set search_path='' as $$
declare v_endpoint text;v_key text;v_request bigint;
begin
 select endpoint into v_endpoint from icue_support.cleanup_config where id;
 if v_endpoint is null then return null; end if;
 select decrypted_secret into v_key from vault.decrypted_secrets where name='icue_support_cleanup_key';
 select net.http_post(url:=v_endpoint,headers:=jsonb_build_object('Content-Type','application/json','x-cleanup-key',v_key),body:='{"action":"cleanup"}'::jsonb,timeout_milliseconds:=10000) into v_request;
 return v_request;
end;
$$;
create function icue_support.install_cleanup(p_endpoint text) returns void language plpgsql security definer set search_path='' as $$
declare v_key text;
begin
 if p_endpoint !~ '^https://[a-z0-9]+\.supabase\.co/functions/v1/support-chat-files$' then raise exception 'Invalid cleanup endpoint'; end if;
 select decrypted_secret into v_key from vault.decrypted_secrets where name='icue_support_cleanup_key';
 if v_key is null then
  v_key:=encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex');
  perform vault.create_secret(v_key,'icue_support_cleanup_key');
 end if;
 update icue_support.cleanup_config set endpoint=p_endpoint,key_hash=sha256(convert_to(v_key,'UTF8')) where id;
 perform cron.schedule('icue-support-guest-cleanup','*/5 * * * *','select icue_support.dispatch_cleanup()');
end;
$$;
